  /** string traduzida com interpolação {var} */
  LA.t = function (key, vars) {
    let s = (D[LA.lang] && D[LA.lang][key]);
    if (s == null) s = D.en[key];
    if (s == null) s = D.pt[key];
    if (s == null) return key;
    if (typeof s === 'string' && vars) s = s.replace(/\{(\w+)\}/g, (m, k) => (vars[k] != null ? vars[k] : m));
    return s;
  };
